    [Fact]
    public async Task ConcurrentApproveAndReject_LeaveExactlyOneFinalDecision()
    {
        using var temp = new TempState();
        temp.CreateService().Propose(new ProposeRequest("req-1", "maker-a", BusinessDate, Reason, Evidence));

        var start = new ManualResetEventSlim(false);
        var deciders = new[]
        {
            ("checker-b", "approve"), ("checker-c", "reject"), ("checker-b", "approve"),
            ("checker-c", "reject"), ("checker-d", "approve"), ("checker-e", "reject")
        };

        var tasks = deciders.Select(decider => Task.Run(() =>
        {
            var service = temp.CreateService();
            start.Wait();
            return service.Decide(new DecideRequest("req-1", decider.Item1, decider.Item2));
        })).ToArray();

        start.Set();
        var results = await Task.WhenAll(tasks);

        Assert.All(results, r => Assert.Contains(
            r.Status,
            new[] { AuditStatus.Accepted, AuditStatus.Idempotent, AuditStatus.Rejected }));
        Assert.Single(results.Where(r => r.Status == AuditStatus.Accepted));

        var entries = ExportEntries(temp, temp.CreateService());
        var terminal = Assert.Single(entries.Where(e => AuditAction.IsTerminal((string?)e["action"])));
        Assert.False(string.IsNullOrWhiteSpace((string?)terminal["checker"]));
        Assert.NotEqual((string?)terminal["proposer"], (string?)terminal["checker"]);
        AssertChainIsIntact(entries);
    }

    [Fact]
    public async Task ConcurrentProposalsForDistinctRequests_AllSurviveWithAnIntactChain()
    {
        using var temp = new TempState();

        var tasks = Enumerable.Range(1, 8).Select(i => Task.Run(() =>
            temp.CreateService().Propose(
                new ProposeRequest($"req-{i}", $"maker-{i}", BusinessDate, Reason, Evidence)))).ToArray();

        var results = await Task.WhenAll(tasks);
        Assert.All(results, r => Assert.Equal(AuditStatus.Accepted, r.Status));

        var entries = ExportEntries(temp, temp.CreateService());
        Assert.Equal(8, entries.Count);
        AssertChainIsIntact(entries);
    }

    [Fact]
    public void Export_ContainsFullHistoryForEveryRequestInRange()
    {
        using var temp = new TempState();
        var service = temp.CreateService();

        service.Propose(new ProposeRequest("req-approved", "maker-a", BusinessDate, Reason, Evidence));
        service.Propose(new ProposeRequest("req-rejected", "maker-a", BusinessDate, Reason, Evidence));
        service.Decide(new DecideRequest("req-approved", "checker-b", "approve"));
        service.Decide(new DecideRequest("req-rejected", "checker-c", "reject"));

        var entries = ExportEntries(temp, service);

        Assert.Equal(4, entries.Count);
        Assert.Equal(2, entries.Count(e => (string?)e["requestId"] == "req-approved"));
        Assert.Equal(2, entries.Count(e => (string?)e["requestId"] == "req-rejected"));
        Assert.Contains(entries, e => (string?)e["action"] == "APPROVED" && (string?)e["checker"] == "checker-b");
        Assert.Contains(entries, e => (string?)e["action"] == "REJECTED" && (string?)e["checker"] == "checker-c");
        AssertChainIsIntact(entries);
    }

    [Fact]
    public void Export_HonoursTheInclusiveDateRange()
    {
        using var temp = new TempState();
        var service = temp.CreateService();

        service.Propose(new ProposeRequest("req-early", "maker-a", "2024-06-02", Reason, Evidence));
        service.Propose(new ProposeRequest("req-inside", "maker-a", "2024-06-03", Reason, Evidence));
        service.Propose(new ProposeRequest("req-late", "maker-a", "2024-06-05", Reason, Evidence));

        var inRange = ExportEntries(temp, service, "2024-06-03", "2024-06-05");
        Assert.Equal(
            new[] { "req-inside", "req-late" },
            inRange.Select(e => (string?)e["requestId"]).ToArray());

        var singleDay = ExportEntries(temp, service, "2024-06-02", "2024-06-02");
        Assert.Equal("req-early", (string?)Assert.Single(singleDay)["requestId"]);
    }

    [Fact]
    public void Export_WritesParseableJsonToTheRequestedPath()
    {
        using var temp = new TempState();
        var service = temp.CreateService();
        service.Propose(new ProposeRequest("req-1", "maker-a", BusinessDate, Reason, Evidence));
        service.Decide(new DecideRequest("req-1", "checker-b", "approve"));

        var result = service.Export(new ExportRequest("2024-06-01", "2024-06-30", temp.ExportPath));

        Assert.Equal(AuditStatus.Completed, result.Status);
        Assert.True(File.Exists(temp.ExportPath));

        var document = JsonNode.Parse(File.ReadAllText(temp.ExportPath))!;
        var entries = AuditTestSupport.EntryObjects(document).ToList();

        Assert.Equal(2, entries.Count);
        Assert.Equal(2, (int?)document["entryCount"]);
        AssertChainIsIntact(entries);
    }

    [Fact]
    public void Export_WithInvertedRange_IsRejected()
    {
        using var temp = new TempState();
        var service = temp.CreateService();

        var result = service.Export(new ExportRequest("2024-06-05", "2024-06-01", temp.ExportPath));

        Assert.Equal(AuditStatus.Rejected, result.Status);
        Assert.False(File.Exists(temp.ExportPath));
    }

    [Fact]
    public void History_SurvivesAcrossSeparateServiceInstances()
    {
        using var temp = new TempState();

        temp.CreateService().Initialize();
        temp.CreateService().Propose(new ProposeRequest("req-1", "maker-a", BusinessDate, Reason, Evidence));
        temp.CreateService().Decide(new DecideRequest("req-1", "checker-b", "approve"));

        var entries = ExportEntries(temp, temp.CreateService());

        Assert.Equal(2, entries.Count);
        AssertChainIsIntact(entries);
    }

    [Fact]
    public void Ledger_IsAppendOnly_AndNeverRewritesAcceptedEntries()
    {
        using var temp = new TempState();
        var store = new AuditLedgerStore(temp.StateDirectory);
        var service = new AuditWorkflowService(store);

        service.Propose(new ProposeRequest("req-1", "maker-a", BusinessDate, Reason, Evidence));
        var afterProposal = File.ReadAllText(store.LedgerPath);

        service.Decide(new DecideRequest("req-1", "checker-b", "approve"));
        var afterDecision = File.ReadAllText(store.LedgerPath);

        Assert.StartsWith(afterProposal, afterDecision, StringComparison.Ordinal);
        Assert.Equal(2, afterDecision.Split('\n', StringSplitOptions.RemoveEmptyEntries).Length);
    }

    internal static void AssertChainIsIntact(IReadOnlyList<JsonObject> entries)
    {
        string? previousHash = null;

        for (var i = 0; i < entries.Count; i++)
        {
            var entry = entries[i];

            Assert.Equal(i + 1, (int?)entry["sequence"]);
            Assert.Equal(previousHash, entry["previousHash"]?.GetValue<string>());

            var hash = (string?)entry["hash"];
            Assert.False(string.IsNullOrWhiteSpace(hash));
            Assert.Equal(64, hash!.Length);
            Assert.Equal(hash, hash.ToLowerInvariant());
            Assert.Equal(hash, AuditTestSupport.RecomputeHash(entry));

            previousHash = hash;
        }
    }

    private static List<JsonObject> ExportEntries(
        TempState temp,
        AuditWorkflowService service,
        string from = "2024-01-01",
        string to = "2024-12-31")
    {
        var result = service.Export(new ExportRequest(from, to, temp.ExportPath));
        return AuditTestSupport.EntryObjects(result.Payload).ToList();
    }
}

