        var deciders = new[]
        {
            ("checker-b", "approve"), ("checker-c", "reject"), ("checker-b", "approve"),
            ("checker-c", "reject"), ("checker-d", "approve"), ("checker-e", "reject")
        };

        var tasks = deciders.Select(decider => Task.Run(() =>
        {
            var service = temp.CreateService();
            start.Wait();
            return service.Decide(new DecideRequest("req-1", decider.Item1, decider.Item2));
        })).ToArray();

        start.Set();
        var results = await Task.WhenAll(tasks);

        Assert.All(results, r => Assert.Contains(
            r.Status,
            new[] { AuditStatus.Accepted, AuditStatus.Idempotent, AuditStatus.Rejected }));
        Assert.Single(results.Where(r => r.Status == AuditStatus.Accepted));

        var entries = ExportEntries(temp, temp.CreateService());
        var terminal = Assert.Single(entries.Where(e => AuditAction.IsTerminal((string?)e["action"])));
        Assert.False(string.IsNullOrWhiteSpace((string?)terminal["checker"]));
        Assert.NotEqual((string?)terminal["proposer"], (string?)terminal["checker"]);
        AssertChainIsIntact(entries);
    }

